                keyValue: 7,
                column: "schema",
                value: "{\"schemaVersion\":2,\"title\":\"Arkusz pierwszej oceny w służbie cywilnej\",\"legalBasis\":\"Rozporządzenie Prezesa Rady Ministrów z dnia 23 lipca 2015 r. w sprawie szczegółowych warunków i sposobu dokonywania pierwszej oceny w służbie cywilnej (Dz. U. poz. 1144), załącznik nr 2\",\"initialStatus\":\"planned\",\"statuses\":[{\"key\":\"planned\",\"label\":\"Zaplanowana\"},{\"key\":\"interview_done\",\"label\":\"Po rozmowie wstępnej\"},{\"key\":\"report_submitted\",\"label\":\"Sprawozdanie złożone\"},{\"key\":\"evaluated\",\"label\":\"Ocena sporządzona\"},{\"key\":\"completed\",\"label\":\"Zakończona\",\"final\":true},{\"key\":\"cancelled\",\"label\":\"Anulowana\",\"final\":true}],\"stages\":[{\"key\":\"initial_interview\",\"title\":\"Rozmowa wstępna\",\"phase\":\"Rozmowa wstępna\",\"deadline\":{\"anchor\":\"start\",\"latest\":{\"days\":21}},\"completesTo\":\"interview_done\",\"legalRef\":\"§ 3\",\"topics\":[{\"text\":\"Sposób dokonywania pierwszej oceny\",\"legalRef\":\"§ 3 pkt 1\"},{\"text\":\"Główne obowiązki z opisu stanowiska i oczekiwania co do sposobu ich wykonywania\",\"legalRef\":\"§ 3 pkt 2\"},{\"text\":\"Oczekiwania co do postawy, zaangażowania, postępów, relacji ze współpracownikami i terminowości (opisy elementów oceny)\",\"legalRef\":\"§ 3 pkt 3\"},{\"text\":\"Termin na złożenie sprawozdania\",\"legalRef\":\"§ 3 pkt 4\"}]},{\"key\":\"report\",\"title\":\"Złożenie sprawozdania z zadań realizowanych w przepracowanym okresie\",\"phase\":\"Sprawozdanie\",\"deadline\":{\"anchor\":\"start\",\"latest\":{\"months\":7}},\"completesTo\":\"report_submitted\",\"selfAssessment\":true,\"legalRef\":\"§ 4 ust. 1\"},{\"key\":\"evaluation\",\"title\":\"Rozmowa oceniająca i pierwsza ocena\",\"phase\":\"Ocena\",\"deadline\":{\"anchor\":\"start\",\"earliest\":{\"months\":8},\"latest\":{\"months\":11}},\"completesTo\":\"evaluated\",\"legalRef\":\"§ 8 ust. 1\",\"topics\":[{\"text\":\"Postawa, zaangażowanie i postępy w pracy, relacje ze współpracownikami, terminowość — elementy oceny\",\"legalRef\":\"§ 2 pkt 1\"},{\"text\":\"Wynik egzaminu ze służby przygotowawczej\",\"legalRef\":\"§ 2 pkt 2\",\"optional\":true},{\"text\":\"Sprawozdanie sporządzone przez ocenianego\",\"legalRef\":\"§ 2 pkt 3\"},{\"text\":\"Kierunki dalszego rozwoju zawodowego i potrzeby\",\"legalRef\":\"§ 7 pkt 1\",\"optional\":true}]},{\"key\":\"acknowledgement\",\"title\":\"Zapoznanie ocenianego z pierwszą oceną\",\"phase\":\"Zapoznanie\",\"deadline\":{\"anchor\":\"stage:evaluation\",\"latest\":{\"days\":7},\"note\":\"Przepis: „niezwłocznie” (§ 11 ust. 1). 7 dni to termin organizacyjny, nie ustawowy.\"},\"completesTo\":\"completed\",\"legalRef\":\"§ 11 ust. 1\"}],\"scales\":{\"first\":[{\"value\":3,\"key\":\"below\",\"label\":\"Poniżej oczekiwań\"},{\"value\":5,\"key\":\"meets\",\"label\":\"Na poziomie oczekiwań\"},{\"value\":7,\"key\":\"above\",\"label\":\"Powyżej oczekiwań\"}]},\"scoring\":{\"scores\":\"elements\",\"average\":\"totalScore\",\"result\":\"result\",\"positiveWhen\":[{\"rule\":\"fieldIn\",\"field\":\"exam\",\"values\":[\"yes\",\"not_applicable\"]},{\"rule\":\"fieldIn\",\"field\":\"reportOnTime\",\"values\":[\"yes\"]},{\"rule\":\"maxCountOfScore\",\"score\":3,\"count\":1},{\"rule\":\"minAverage\",\"value\":5}]},\"sections\":[{\"key\":\"general\",\"part\":\"Część ogólna\",\"title\":\"Dane\",\"stage\":\"initial_interview\",\"fields\":[{\"key\":\"office\",\"type\":\"text\",\"label\":\"Nazwa urzędu\",\"required\":true},{\"key\":\"evaluated\",\"type\":\"person\",\"label\":\"Dane ocenianego\",\"role\":\"evaluated\",\"required\":true},{\"key\":\"hireDate\",\"type\":\"date\",\"label\":\"Data nawiązania stosunku pracy\",\"prefill\":\"employee.hireDate\",\"required\":true,\"hint\":\"Przy zastępstwie: data ustalenia przez strony, że oceniany podlega pierwszej ocenie.\",\"legalRef\":\"§ 3\"},{\"key\":\"supervisor\",\"type\":\"person\",\"label\":\"Dane bezpośredniego przełożonego\",\"role\":\"supervisor\",\"required\":true},{\"key\":\"unitHead\",\"type\":\"person\",\"label\":\"Dane kierującego komórką organizacyjną\",\"role\":\"unitHead\",\"required\":true}]},{\"key\":\"initial_interview\",\"title\":\"Rozmowa wstępna\",\"stage\":\"initial_interview\",\"fields\":[{\"key\":\"initialInterviewDate\",\"type\":\"date\",\"label\":\"Data przeprowadzenia rozmowy wstępnej\",\"required\":true,\"legalRef\":\"§ 4 ust. 2 pkt 1\"},{\"key\":\"reportPeriod\",\"type\":\"dateRange\",\"label\":\"Termin wyznaczony na złożenie sprawozdania\",\"prefill\":\"stage:report\",\"required\":true,\"legalRef\":\"§ 4 ust. 1, ust. 2 pkt 2\"},{\"key\":\"evaluationPeriod\",\"type\":\"dateRange\",\"label\":\"Okres, w którym powinna zostać dokonana pierwsza ocena\",\"prefill\":\"stage:evaluation\",\"required\":true,\"legalRef\":\"§ 4 ust. 2 pkt 3\"},{\"key\":\"initialInterviewSupervisorSignature\",\"type\":\"signature\",\"role\":\"supervisor\",\"label\":\"Potwierdzenie przeprowadzenia rozmowy wstępnej oraz wyznaczenia terminu na złożenie sprawozdania\",\"legalRef\":\"§ 3\"},{\"key\":\"initialInterviewEvaluatedSignature\",\"type\":\"signature\",\"role\":\"evaluated\",\"legalRef\":\"§ 4 ust. 3\"}]},{\"key\":\"evaluation_interview\",\"title\":\"Rozmowa oceniająca\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"evaluationInterviewDate\",\"type\":\"date\",\"label\":\"Data przeprowadzenia rozmowy oceniającej\",\"required\":true,\"legalRef\":\"§ 8 ust. 1\"},{\"key\":\"evaluationInterviewSupervisorSignature\",\"type\":\"signature\",\"role\":\"supervisor\",\"label\":\"Potwierdzenie przeprowadzenia rozmowy oceniającej i omówienia wszystkich wymaganych zagadnień\",\"legalRef\":\"§ 7 pkt 1\"},{\"key\":\"evaluationInterviewEvaluatedSignature\",\"type\":\"signature\",\"role\":\"evaluated\",\"legalRef\":\"§ 7 pkt 1\"}]},{\"key\":\"elements\",\"title\":\"Ocena postawy ocenianego, jego zaangażowania i postępów w pracy, relacji ze współpracownikami oraz terminowości wykonywania zadań\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"elements\",\"type\":\"scores\",\"label\":\"Elementy oceny\",\"scale\":\"first\",\"required\":true,\"items\":[{\"key\":\"reliability\",\"label\":\"Rzetelność\"},{\"key\":\"knowledge\",\"label\":\"Wykorzystywanie wiedzy i doskonalenie zawodowe\"},{\"key\":\"organization\",\"label\":\"Organizacja pracy i orientacja na osiąganie celów\"},{\"key\":\"communication\",\"label\":\"Komunikacja\"},{\"key\":\"cooperation\",\"label\":\"Współpraca\"}],\"legalRef\":\"§ 7 pkt 2, § 9 ust. 1\"},{\"key\":\"elementsIndicators\",\"type\":\"indicatorScores\",\"label\":\"Wskaźniki behawioralne\",\"of\":\"elements\"},{\"key\":\"totalScore\",\"type\":\"average\",\"label\":\"Ocena łączna\",\"of\":\"elements\",\"legalRef\":\"§ 7 pkt 3\",\"computed\":true}]},{\"key\":\"result\",\"title\":\"Pierwsza ocena w służbie cywilnej\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"exam\",\"type\":\"choice\",\"label\":\"Oceniany zaliczył egzamin ze służby przygotowawczej\",\"required\":true,\"options\":[{\"value\":\"yes\",\"label\":\"Tak\"},{\"value\":\"no\",\"label\":\"Nie\"},{\"value\":\"not_applicable\",\"label\":\"Nie dotyczy\"}],\"legalRef\":\"§ 10 ust. 1 pkt 1\"},{\"key\":\"reportOnTime\",\"type\":\"choice\",\"label\":\"Sprawozdanie zostało złożone w wyznaczonym terminie\",\"required\":true,\"options\":[{\"value\":\"yes\",\"label\":\"Tak\"},{\"value\":\"no\",\"label\":\"Nie\"}],\"legalRef\":\"§ 10 ust. 1 pkt 2\"},{\"key\":\"result\",\"type\":\"choice\",\"label\":\"Pierwsza ocena w służbie cywilnej\",\"required\":true,\"options\":[{\"value\":\"positive\",\"label\":\"Pozytywna\"},{\"value\":\"negative\",\"label\":\"Negatywna\"}],\"legalRef\":\"§ 10\",\"computed\":true},{\"key\":\"justification\",\"type\":\"longText\",\"label\":\"Uzasadnienie przyznanej oceny\",\"requiredWhen\":{\"field\":\"result\",\"in\":[\"negative\"]},\"legalRef\":\"§ 10 ust. 4–5\"},{\"key\":\"developmentConclusions\",\"type\":\"longText\",\"label\":\"Wnioski dotyczące rozwoju zawodowego ocenianego\",\"visibleWhen\":{\"field\":\"result\",\"in\":[\"positive\"]},\"legalRef\":\"§ 10 ust. 6\"}]},{\"key\":\"confirmation\",\"title\":\"Potwierdzenie dokonania pierwszej oceny w służbie cywilnej\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"confirmationSupervisorSignature\",\"type\":\"signature\",\"role\":\"supervisor\"},{\"key\":\"confirmationUnitHeadSignature\",\"type\":\"signature\",\"role\":\"unitHead\"}]},{\"key\":\"acknowledgement\",\"title\":\"Zapoznanie z oceną\",\"stage\":\"acknowledgement\",\"fields\":[{\"key\":\"acknowledgementSignature\",\"type\":\"signature\",\"role\":\"evaluated\",\"label\":\"Zapoznałam(-łem) się z pierwszą oceną w służbie cywilnej.\",\"legalRef\":\"§ 11 ust. 1\"}]}],\"competencyModel\":{\"source\":\"Model kompetencji służby cywilnej (Kompas Kompetencji, Ministerstwo Cyfryzacji)\",\"guidance\":[\"Dobierz wskaźniki do zadań i zakresu odpowiedzialności na stanowisku. Poziom „na poziomie oczekiwań” opisuje standard wykonania w tym zakresie.\",\"Oprzyj ocenę na konkretnych przykładach z ocenianego okresu. Zapisz sytuację, działanie i jego rezultat. Uwzględnij powtarzalność zachowania, złożoność sytuacji i dostępne uprawnienia.\",\"Jeśli brak było okazji do zaobserwowania zachowania, odnotuj brak podstaw do oceny danego wskaźnika.\"],\"competencies\":{\"reliability\":{\"name\":\"Rzetelność\",\"indicators\":[{\"key\":\"reliability_1\",\"text\":\"Wykonywanie zadań zgodnie z obowiązującymi standardami (przepisami, zasadami, procedurami) oraz dbałość o jakość rezultatów.\",\"levels\":{\"below\":\"Stosuje podstawowe procedury, lecz pomija część wymagań lub sprawdza rezultat dopiero po zwróceniu uwagi.\",\"meets\":\"Sprawdza aktualne wymagania, stosuje właściwą procedurę i weryfikuje rezultat przed przekazaniem.\",\"above\":\"W nietypowych sprawach ustala, które wymagania mają zastosowanie, i dobiera dodatkowe kontrole do ryzyka błędu.\"}},{\"key\":\"reliability_2\",\"text\":\"Dotrzymywanie zobowiązań (realizacja zadań) w wyznaczonym czasie.\",\"levels\":{\"below\":\"Realizuje zadania w terminie przy przypomnieniach lub zgłasza zagrożenie zbyt późno, by zmienić plan.\",\"meets\":\"Dotrzymuje uzgodnionych terminów. Z wyprzedzeniem zgłasza ryzyko opóźnienia i uzgadnia dalsze kroki.\",\"above\":\"Przy zadaniach zależnych od innych ustala terminy cząstkowe i reaguje na odchylenia, zanim zagrożą zobowiązaniu.\"}}]},\"knowledge\":{\"name\":\"Wykorzystywanie wiedzy i doskonalenie zawodowe\",\"indicators\":[{\"key\":\"knowledge_1\",\"text\":\"Wykorzystywanie wiedzy przy realizacji zadań na zajmowanym stanowisku pracy.\",\"levels\":{\"below\":\"Stosuje podstawową wiedzę w zadaniach powtarzalnych, ale przy zmianie warunków potrzebuje wskazania właściwej metody.\",\"meets\":\"Dobiera i stosuje wiedzę merytoryczną odpowiednią do zadania. W razie wątpliwości potwierdza przyjęty sposób działania.\",\"above\":\"Łączy wiedzę z kilku obszarów, by rozwiązać nietypową sprawę, i uzasadnia dobór metody oraz granice jej stosowania.\"}},{\"key\":\"knowledge_2\",\"text\":\"Doskonalenie wiedzy i umiejętności niezbędnych do wykonywania zadań na zajmowanym stanowisku pracy, w szczególności wyszukiwanie i pozyskiwanie wiedzy, korzystanie z dobrych praktyk i doświadczeń innych.\",\"levels\":{\"below\":\"Uzupełnia wiedzę po wskazaniu konkretnej luki, lecz potrzebuje wsparcia, by zastosować nowe umiejętności.\",\"meets\":\"Rozpoznaje luki istotne dla swoich zadań, korzysta z aktualnych materiałów i doświadczeń innych oraz stosuje zdobytą wiedzę.\",\"above\":\"Planuje rozwój pod kątem nadchodzących zadań, testuje wybrane praktyki i sprawdza ich wpływ na własną pracę.\"}},{\"key\":\"knowledge_3\",\"text\":\"Korzystanie z dostępnych źródeł informacji, rozwiązań i technologii.\",\"levels\":{\"below\":\"Korzysta ze znanego źródła lub narzędzia, lecz potrzebuje wsparcia w ocenie jego aktualności albo przydatności.\",\"meets\":\"Dobiera dopuszczone źródła i narzędzia do celu oraz sprawdza aktualność informacji i poprawność wyniku.\",\"above\":\"Porównuje dostępne źródła i rozwiązania, rozstrzyga rozbieżności i dobiera narzędzie z uwzględnieniem jakości, czasu oraz zasad ochrony danych.\"}}]},\"organization\":{\"name\":\"Organizacja pracy i orientacja na osiąganie celów\",\"indicators\":[{\"key\":\"organization_1\",\"text\":\"Określanie sposobu realizacji zadań/celów.\",\"levels\":{\"below\":\"Ustala podstawowe kroki, lecz plan wymaga uzupełnienia o zależności, terminy lub oczekiwany rezultat.\",\"meets\":\"Określa rezultat, główne kroki, ich kolejność i terminy odpowiednie do zadania.\",\"above\":\"Dla złożonego zadania uwzględnia zależności, punkty kontroli i sposób postępowania przy przewidywalnych odchyleniach.\"}},{\"key\":\"organization_2\",\"text\":\"Realizowanie zadań/celów w kolejności uwzględniającej ich wagę i pilność (ustalanie priorytetów działania).\",\"levels\":{\"below\":\"Uwzględnia pilność, lecz potrzebuje wsparcia, gdy zadania o podobnych terminach mają różną wagę.\",\"meets\":\"Ustala kolejność zadań, uwzględniając ich wagę, pilność, terminy i wpływ na inne działania.\",\"above\":\"Przy zbiegu ważnych zadań porównuje skutki przesunięć, aktualizuje priorytety i uzgadnia wpływ na zobowiązania.\"}},{\"key\":\"organization_3\",\"text\":\"Dobieranie niezbędnych zasobów umożliwiających realizację zadań/celów.\",\"levels\":{\"below\":\"Wskazuje część zasobów, lecz potrzebuje pomocy w oszacowaniu dostępności, czasu lub nakładu pracy.\",\"meets\":\"Określa potrzebny czas, informacje, narzędzia i wsparcie. Sprawdza dostępność zasobów przed realizacją.\",\"above\":\"Dla złożonych zadań porównuje warianty wykorzystania zasobów i uzgadnia zastępstwa lub rezerwy.\"}},{\"key\":\"organization_4\",\"text\":\"Dostosowywanie się do zmieniających się okoliczności.\",\"levels\":{\"below\":\"Zmienia sposób pracy po wskazaniu problemu, lecz wymaga wsparcia w ocenie konsekwencji dla dalszych działań.\",\"meets\":\"Po zmianie warunków aktualizuje sposób pracy i informuje zainteresowanych o skutkach dla uzgodnionego planu.\",\"above\":\"Przy nagłej zmianie porównuje możliwe reakcje, wdraża uzgodnione rozwiązanie i zabezpiecza najważniejsze zobowiązania.\"}},{\"key\":\"organization_5\",\"text\":\"Wytrwałość i zaangażowanie w realizację zadań/celów.\",\"levels\":{\"below\":\"Po trudnościach wraca do zadania po przypomnieniu lub pozostawia uzgodnione działania bez domknięcia.\",\"meets\":\"Realizuje uzgodnione etapy, reaguje na przeszkody i doprowadza zadanie do zakończenia lub uzgodnionego przekazania.\",\"above\":\"Przy powtarzających się przeszkodach podejmuje kolejne uzasadnione działania i pozyskuje wsparcie potrzebne do zakończenia zadania.\"}}]},\"communication\":{\"name\":\"Komunikacja\",\"indicators\":[{\"key\":\"communication_1\",\"text\":\"Koncentrowanie się na wypowiedzi rozmówcy i dbanie o wzajemne zrozumienie.\",\"levels\":{\"below\":\"Wysłuchuje wypowiedzi, lecz pozostawia istotne niejasności i sprawdza swoje rozumienie dopiero po zwróceniu uwagi.\",\"meets\":\"Pozwala rozmówcy dokończyć wypowiedź, dopytuje o niejasności i potwierdza kluczowe ustalenia.\",\"above\":\"W rozmowie o niejednoznacznych kwestiach parafrazuje stanowisko rozmówcy i wyjaśnia rozbieżności w interpretacji.\"}},{\"key\":\"communication_2\",\"text\":\"Wypowiadanie się w sposób jasny i precyzyjny, dostosowany do sytuacji i rozmówcy (dobieranie stylu, języka i treści).\",\"levels\":{\"below\":\"Przekazuje sedno sprawy, lecz rozmówca musi dopytywać o znaczenie, kontekst lub dalsze kroki.\",\"meets\":\"Porządkuje wypowiedź, wyjaśnia potrzebne pojęcia i dostosowuje język oraz szczegółowość do rozmówcy i sytuacji.\",\"above\":\"Wyjaśnia złożone kwestie prostym językiem, zachowując istotne rozróżnienia, i dostosowuje wyjaśnienie do pytań rozmówcy.\"}},{\"key\":\"communication_3\",\"text\":\"Formułowanie jasnych i precyzyjnych wypowiedzi pisemnych dostosowanych do sytuacji i odbiorcy (dobieranie stylu, języka i treści).\",\"levels\":{\"below\":\"Przekazuje główną informację, lecz tekst wymaga uzupełnienia kontekstu, uporządkowania albo doprecyzowania ustaleń.\",\"meets\":\"Formułuje spójny tekst. Wskazuje cel i kluczowe informacje, a w razie potrzeby określa dalsze działanie i termin.\",\"above\":\"W złożonej sprawie wyodrębnia najważniejszą informację, oddziela ustalenia od kwestii otwartych i precyzuje odpowiedzialność.\"}},{\"key\":\"communication_4\",\"text\":\"Przedstawianie przekonujących argumentów odpowiednio do sytuacji.\",\"levels\":{\"below\":\"Podaje częściowe uzasadnienie, lecz pomija przesłanki ważne dla rozmówcy lub podstawowe zastrzeżenia.\",\"meets\":\"Uzasadnia stanowisko trafnymi faktami i przykładami oraz odpowiada na główne zastrzeżenia.\",\"above\":\"W złożonej sprawie dobiera argumenty do kryteriów decyzji, odpowiada na kontrargumenty i objaśnia ograniczenia przywołanych danych.\"}}]},\"cooperation\":{\"name\":\"Współpraca\",\"indicators\":[{\"key\":\"cooperation_1\",\"text\":\"Włączanie się w działania realizowane razem z innymi osobami, jeśli istnieje taka możliwość.\",\"levels\":{\"below\":\"Włącza się po ponownej prośbie lub wykonuje swoją część bez uzgodnienia zależności z innymi osobami.\",\"meets\":\"Podejmuje uzgodnioną część wspólnego zadania, koordynuje ją z innymi i przekazuje rezultaty zgodnie z ustaleniami.\",\"above\":\"Samodzielnie rozpoznaje, gdzie potrzebna jest współpraca, i uzgadnia podział działań lub oferuje konkretne wsparcie.\"}},{\"key\":\"cooperation_2\",\"text\":\"Dbanie o przepływ informacji.\",\"levels\":{\"below\":\"Przekazuje informacje po przypomnieniu albo pomija kontekst i odbiorcy muszą dopytywać o ustalenia.\",\"meets\":\"Przekazuje uprawnionym odbiorcom aktualne informacje, ustalenia i zmiany w czasie pozwalającym wykorzystać je w pracy.\",\"above\":\"Z wyprzedzeniem określa, komu i kiedy potrzebna jest informacja, oraz potwierdza dotarcie komunikatów istotnych dla dalszych działań.\"}},{\"key\":\"cooperation_3\",\"text\":\"Dbanie o dobrą atmosferę i otwartość we współpracy.\",\"levels\":{\"below\":\"Utrzymuje rzeczowy ton w typowych sytuacjach, lecz przy napięciu pomija głos innych lub wycofuje się z potrzebnego uzgodnienia.\",\"meets\":\"Odnosi się z szacunkiem do innych osób, zaprasza do wypowiedzi i omawia rozbieżności w odniesieniu do zadania.\",\"above\":\"Reaguje na sygnały napięcia, nazywa przedmiot rozbieżności i umożliwia stronom przedstawienie perspektyw.\"}},{\"key\":\"cooperation_4\",\"text\":\"Dostrzeganie wkładu pracy innych osób.\",\"levels\":{\"below\":\"Wymienia osoby uczestniczące w zadaniu po przypomnieniu albo dziękuje ogólnie, bez wskazania wkładu.\",\"meets\":\"Wskazuje konkretny wkład współpracowników i przypisuje autorstwo zgodnie z przebiegiem prac.\",\"above\":\"Zauważa także mniej widoczny wkład i wyjaśnia jego znaczenie dla wyniku, dobierając formę uznania do sytuacji.\"}},{\"key\":\"cooperation_5\",\"text\":\"Branie pod uwagę zdania innych osób.\",\"levels\":{\"below\":\"Zbiera opinie, lecz wybiórczo je rozważa lub pozostawia bez odpowiedzi uwagi istotne dla zadania.\",\"meets\":\"Zasięga opinii osób związanych z zadaniem, rozważa ich argumenty i wyjaśnia sposób uwzględnienia istotnych uwag.\",\"above\":\"Aktywnie zbiera także odmienne stanowiska i porównuje je według kryteriów dotyczących wspólnego celu.\"}},{\"key\":\"cooperation_6\",\"text\":\"Dzielenie się wiedzą i doświadczeniem.\",\"levels\":{\"below\":\"Udostępnia informacje po ponownej prośbie lub w formie wymagającej dodatkowych wyjaśnień przed użyciem.\",\"meets\":\"Przekazuje uprawnionym osobom potrzebne informacje, materiały i przykłady w formie pozwalającej wykonać zadanie.\",\"above\":\"Z własnej inicjatywy dzieli się wskazówkami z ukończonych spraw, objaśnia ich zastosowanie i odpowiada na pytania.\"}}]}}}}");
        }
    }
}
